def solve(inputs, readings):
    diet = readings['diet']
    ingredients = inputs['ingredients']
    servings = inputs['servings']

    remaining = []
    for ingredient in ingredients:
        kind = ingredient['kind']
        if diet == 'vegan' and kind in ('dairy', 'meat'):
            continue
        if diet == 'vegetarian' and kind == 'meat':
            continue
        grams = int((ingredient['grams'] * servings / 4) + 0.5)
        remaining.append((ingredient['name'], grams))

    total = sum(grams for name, grams in remaining)
    heaviest = 'none'
    if remaining:
        heaviest = remaining[0][0]
        max_grams = remaining[0][1]
        for name, grams in remaining[1:]:
            if grams > max_grams:
                heaviest = name
                max_grams = grams

    return f"{diet}: {len(remaining)} ingredients, {total}g, heaviest {heaviest}"

def solve(inputs, readings):
    vans = {}
    total_km = 0
    total_litres_tenths = 0

    for line in inputs["trips"].splitlines():
        van, km, litres = (part.strip() for part in line.split("|"))
        km = int(km)
        whole, decimal = litres.split(".")
        litres_tenths = int(whole) * 10 + int(decimal)
        if van not in vans:
            vans[van] = [0, 0]
        vans[van][0] += km
        vans[van][1] += litres_tenths
        total_km += km
        total_litres_tenths += litres_tenths

    def rounded_tenths(litres_tenths, km):
        numerator = litres_tenths * 100
        return (2 * numerator + km) // (2 * km)

    def display(tenths):
        return str(tenths // 10) + "." + str(tenths % 10)

    worst_van = None
    for van in sorted(vans):
        if worst_van is None:
            worst_van = van
        else:
            km, litres_tenths = vans[van]
            best_km, best_litres_tenths = vans[worst_van]
            if litres_tenths * best_km > best_litres_tenths * km:
                worst_van = van

    worst_km, worst_litres_tenths = vans[worst_van]
    worst_consumption = rounded_tenths(worst_litres_tenths, worst_km)
    fleet_consumption = rounded_tenths(total_litres_tenths, total_km)
    problem = readings["reported_problem"]
    action = "no visit" if problem == "none" else "book " + problem
    return worst_van + " worst at " + display(worst_consumption) + " l/100km | fleet " + display(fleet_consumption) + " l/100km | " + action

import re

def solve(inputs, readings):
    country = readings['destination']
    rates = {'UK': 20, 'Ireland': 23, 'Spain': 21, 'Italy': 22}
    lines = inputs['lines']

    if isinstance(lines, str):
        tokens = re.findall(r'"(?:\\.|[^"\\])*"|[{}\[\]:,]|-?\d+(?:\.\d+)?|true|false|null', lines)
        parsed = []
        i = 0
        while i < len(tokens):
            if tokens[i] != '{':
                i += 1
                continue
            i += 1
            fields = {}
            while i < len(tokens) and tokens[i] != '}':
                if tokens[i] in (',', ':'):
                    i += 1
                    continue
                key = tokens[i][1:-1]
                i += 1
                if i < len(tokens) and tokens[i] == ':':
                    i += 1
                if i < len(tokens):
                    fields[key] = tokens[i]
                    i += 1
            if i < len(tokens):
                i += 1
            parsed.append(fields)
        lines = parsed

    net_cents = 0
    for line in lines:
        qty = int(line['qty'])
        price = line['unit_price']
        if not isinstance(price, str):
            price = str(price)
        whole, fraction = price.split('.')
        unit_cents = int(whole) * 100 + int(fraction)
        net_cents += qty * unit_cents

    vat_cents = (net_cents * rates[country] + 50) // 100
    gross_cents = net_cents + vat_cents

    def money(cents):
        return str(cents // 100) + '.' + str(cents % 100).zfill(2)

    return country + ' | net ' + money(net_cents) + ' | VAT ' + money(vat_cents) + ' | gross ' + money(gross_cents) + ' EUR | ' + str(len(lines)) + ' lines'
